-- DeviDex user data on Cloudflare D1 (SQLite).
--
-- Only data that is private, per-user, or written by people lives here. The
-- Pokémon catalogue and reference tables are static files (public/data), so
-- columns like form_id, species_id and game_id point at ids in those files and
-- have no foreign key: the Worker checks them instead.
--
-- Logins stay on Supabase Auth for now. A user's id is their Supabase user id
-- (a UUID string), and profiles is the root every user table hangs off.
--
-- Conventions, because SQLite is not Postgres:
--   uuid        -> TEXT, generated by the Worker (crypto.randomUUID). Every
--                  TEXT primary key is NOT NULL: SQLite would otherwise allow NULL ids.
--   timestamptz -> TEXT in ISO 8601 UTC, e.g. 2026-11-03T23:30:00.000Z
--   boolean     -> INTEGER 0/1, checked
--   text[]      -> TEXT holding a JSON array, checked
--   regex CHECKs-> GLOB and length checks; anything SQLite can't express is
--                  enforced in the Worker
-- Foreign keys are enforced: D1 runs with PRAGMA foreign_keys = ON.

------------------------------------------------------------------------------
-- Accounts

CREATE TABLE profiles (
  id TEXT PRIMARY KEY NOT NULL,                          -- Supabase auth user id
  username TEXT UNIQUE,
  display_name TEXT,
  role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
  avatar_path TEXT,
  home_friend_code TEXT,
  home_friend_code_public INTEGER NOT NULL DEFAULT 0 CHECK (home_friend_code_public IN (0, 1)),
  profile_public INTEGER NOT NULL DEFAULT 1 CHECK (profile_public IN (0, 1)),
  collection_public INTEGER NOT NULL DEFAULT 0 CHECK (collection_public IN (0, 1)),
  collection_friends_visible INTEGER NOT NULL DEFAULT 1 CHECK (collection_friends_visible IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (
    username IS NULL OR (
      length(username) BETWEEN 3 AND 20
      AND username NOT GLOB '*[^A-Za-z0-9_-]*'
      AND lower(username) NOT IN ('admin', 'administrator', 'devidex', 'support', 'moderator',
                                  'official', 'system', 'staff', 'help', 'security')
    )
  )
);
CREATE UNIQUE INDEX profiles_username_lower_unique ON profiles (lower(username)) WHERE username IS NOT NULL;

-- New profiles get the default collection setup, as on Supabase.
CREATE TRIGGER profiles_create_default_collection_view AFTER INSERT ON profiles
BEGIN
  INSERT OR IGNORE INTO user_collection_views (id, user_id, name, preset_id, goal, is_active)
  VALUES (lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)), 2) || '-' ||
          substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)), 2) || '-' || hex(randomblob(6))),
          NEW.id, 'Main Collection', 'standard', 'living', 1);
END;

------------------------------------------------------------------------------
-- Collections

CREATE TABLE collection_progress (
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  form_id INTEGER NOT NULL,
  normal_owned INTEGER NOT NULL DEFAULT 0 CHECK (normal_owned IN (0, 1)),
  shiny_owned INTEGER NOT NULL DEFAULT 0 CHECK (shiny_owned IN (0, 1)),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id, form_id)
) WITHOUT ROWID;
CREATE INDEX collection_progress_form_idx ON collection_progress (form_id);

CREATE TABLE game_collection_progress (
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  game_id INTEGER NOT NULL,
  species_id INTEGER NOT NULL,
  normal_owned INTEGER NOT NULL DEFAULT 0 CHECK (normal_owned IN (0, 1)),
  shiny_owned INTEGER NOT NULL DEFAULT 0 CHECK (shiny_owned IN (0, 1)),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id, game_id, species_id)
) WITHOUT ROWID;

CREATE TABLE game_form_collection_progress (
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  game_id INTEGER NOT NULL,
  form_id INTEGER NOT NULL,
  normal_owned INTEGER NOT NULL DEFAULT 0 CHECK (normal_owned IN (0, 1)),
  shiny_owned INTEGER NOT NULL DEFAULT 0 CHECK (shiny_owned IN (0, 1)),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id, game_id, form_id)
) WITHOUT ROWID;

CREATE TABLE game_dex_activity (
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  set_id INTEGER NOT NULL,
  game_id INTEGER NOT NULL,
  started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_activity_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id, set_id)
) WITHOUT ROWID;
CREATE INDEX game_dex_activity_user_idx ON game_dex_activity (user_id, last_activity_at DESC);

CREATE TABLE user_collection_views (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 40),
  preset_id TEXT NOT NULL DEFAULT 'standard'
    CHECK (preset_id IN ('standard', 'forms', 'gender-forms', 'shiny', 'shiny-forms', 'battle-forms', 'everything', 'custom')),
  goal TEXT NOT NULL DEFAULT 'living' CHECK (goal IN ('living', 'shiny', 'both')),
  include_regional INTEGER NOT NULL DEFAULT 0 CHECK (include_regional IN (0, 1)),
  include_alternate INTEGER NOT NULL DEFAULT 0 CHECK (include_alternate IN (0, 1)),
  include_pattern INTEGER NOT NULL DEFAULT 0 CHECK (include_pattern IN (0, 1)),
  include_gender INTEGER NOT NULL DEFAULT 0 CHECK (include_gender IN (0, 1)),
  include_battle INTEGER NOT NULL DEFAULT 0 CHECK (include_battle IN (0, 1)),
  include_special INTEGER NOT NULL DEFAULT 0 CHECK (include_special IN (0, 1)),
  is_active INTEGER NOT NULL DEFAULT 0 CHECK (is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE UNIQUE INDEX user_collection_views_one_active_per_user ON user_collection_views (user_id) WHERE is_active = 1;
CREATE UNIQUE INDEX user_collection_views_name_ci_unique ON user_collection_views (user_id, lower(trim(name)));
CREATE INDEX user_collection_views_user_created_idx ON user_collection_views (user_id, created_at);

CREATE TRIGGER user_collection_views_limit BEFORE INSERT ON user_collection_views
WHEN (SELECT count(*) FROM user_collection_views WHERE user_id = NEW.user_id) >= 20
BEGIN
  SELECT RAISE(ABORT, 'DeviDex currently supports up to 20 saved collection setups per account.');
END;

CREATE TABLE user_form_preferences (
  user_id TEXT PRIMARY KEY NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  include_regional INTEGER NOT NULL DEFAULT 0 CHECK (include_regional IN (0, 1)),
  include_alternate INTEGER NOT NULL DEFAULT 0 CHECK (include_alternate IN (0, 1)),
  include_pattern INTEGER NOT NULL DEFAULT 0 CHECK (include_pattern IN (0, 1)),
  include_gender INTEGER NOT NULL DEFAULT 0 CHECK (include_gender IN (0, 1)),
  include_battle INTEGER NOT NULL DEFAULT 0 CHECK (include_battle IN (0, 1)),
  include_special INTEGER NOT NULL DEFAULT 0 CHECK (include_special IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE trade_list (
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  form_id INTEGER NOT NULL,
  shiny INTEGER NOT NULL DEFAULT 0 CHECK (shiny IN (0, 1)),
  note TEXT CHECK (note IS NULL OR length(note) <= 140),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id, form_id, shiny)
) WITHOUT ROWID;
CREATE INDEX trade_list_form_shiny_idx ON trade_list (form_id, shiny);

------------------------------------------------------------------------------
-- Friends and blocks

CREATE TABLE friendships (
  id TEXT PRIMARY KEY NOT NULL,
  requester_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  addressee_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  responded_at TEXT,
  CHECK (requester_id <> addressee_id)
);
-- One friendship per pair, whichever way round it was sent.
CREATE UNIQUE INDEX friendships_pair_unique ON friendships (min(requester_id, addressee_id), max(requester_id, addressee_id));
CREATE INDEX friendships_requester_idx ON friendships (requester_id, status);
CREATE INDEX friendships_addressee_idx ON friendships (addressee_id, status);

CREATE TABLE user_blocks (
  blocker_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  blocked_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (blocker_id, blocked_id),
  CHECK (blocker_id <> blocked_id)
) WITHOUT ROWID;
CREATE INDEX user_blocks_blocked_idx ON user_blocks (blocked_id);

------------------------------------------------------------------------------
-- Chat

CREATE TABLE conversations (
  id TEXT PRIMARY KEY NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('direct', 'group')),
  title TEXT CHECK (title IS NULL OR length(title) BETWEEN 1 AND 60),
  direct_key TEXT UNIQUE,
  created_by TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_message_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (
    (kind = 'direct' AND direct_key IS NOT NULL AND title IS NULL)
    OR (kind = 'group' AND direct_key IS NULL AND title IS NOT NULL)
  )
);

CREATE TABLE conversation_members (
  conversation_id TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'member')),
  joined_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_read_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (conversation_id, user_id)
) WITHOUT ROWID;
CREATE INDEX conversation_members_user_idx ON conversation_members (user_id);

CREATE TABLE messages (
  id TEXT PRIMARY KEY NOT NULL,
  conversation_id TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
  sender_id TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  kind TEXT NOT NULL DEFAULT 'text' CHECK (kind IN ('text', 'system')),
  body TEXT NOT NULL CHECK (length(body) <= 2000),
  pokemon_form_id INTEGER,
  pokemon_shiny INTEGER NOT NULL DEFAULT 0 CHECK (pokemon_shiny IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT
);
CREATE INDEX messages_conversation_created_idx ON messages (conversation_id, created_at DESC);
CREATE INDEX messages_sender_created_idx ON messages (sender_id, created_at DESC);

------------------------------------------------------------------------------
-- Forums

CREATE TABLE forum_categories (
  id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE CHECK (length(slug) BETWEEN 2 AND 40 AND slug NOT GLOB '*[^a-z0-9-]*'),
  name TEXT NOT NULL CHECK (length(name) BETWEEN 2 AND 60),
  description TEXT CHECK (description IS NULL OR length(description) <= 240),
  sort_order INTEGER NOT NULL DEFAULT 0,
  admin_only_posts INTEGER NOT NULL DEFAULT 0 CHECK (admin_only_posts IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE forum_posts (
  id TEXT PRIMARY KEY NOT NULL,
  category_id INTEGER NOT NULL REFERENCES forum_categories (id) ON DELETE RESTRICT,
  author_id TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
  body TEXT NOT NULL CHECK (length(body) <= 10000),
  pokemon_form_id INTEGER,
  is_pinned INTEGER NOT NULL DEFAULT 0 CHECK (is_pinned IN (0, 1)),
  is_locked INTEGER NOT NULL DEFAULT 0 CHECK (is_locked IN (0, 1)),
  score INTEGER NOT NULL DEFAULT 0,
  comment_count INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  edited_at TEXT,
  last_activity_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  deleted_at TEXT,
  removed_by_admin INTEGER NOT NULL DEFAULT 0 CHECK (removed_by_admin IN (0, 1))
);
CREATE INDEX forum_posts_author_idx ON forum_posts (author_id, created_at DESC);
CREATE INDEX forum_posts_category_activity_idx ON forum_posts (category_id, last_activity_at DESC);
CREATE INDEX forum_posts_created_idx ON forum_posts (created_at DESC);

CREATE TABLE forum_comments (
  id TEXT PRIMARY KEY NOT NULL,
  post_id TEXT NOT NULL REFERENCES forum_posts (id) ON DELETE CASCADE,
  parent_id TEXT REFERENCES forum_comments (id) ON DELETE CASCADE,
  author_id TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  body TEXT NOT NULL CHECK (length(body) <= 5000),
  depth INTEGER NOT NULL DEFAULT 0 CHECK (depth BETWEEN 0 AND 8),
  score INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  edited_at TEXT,
  deleted_at TEXT,
  removed_by_admin INTEGER NOT NULL DEFAULT 0 CHECK (removed_by_admin IN (0, 1))
);
CREATE INDEX forum_comments_author_idx ON forum_comments (author_id, created_at DESC);
CREATE INDEX forum_comments_parent_idx ON forum_comments (parent_id);
CREATE INDEX forum_comments_post_idx ON forum_comments (post_id, created_at);

CREATE TABLE forum_post_votes (
  post_id TEXT NOT NULL REFERENCES forum_posts (id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  value INTEGER NOT NULL CHECK (value IN (-1, 1)),
  PRIMARY KEY (post_id, user_id)
) WITHOUT ROWID;
CREATE INDEX forum_post_votes_user_idx ON forum_post_votes (user_id);

CREATE TABLE forum_comment_votes (
  comment_id TEXT NOT NULL REFERENCES forum_comments (id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  value INTEGER NOT NULL CHECK (value IN (-1, 1)),
  PRIMARY KEY (comment_id, user_id)
) WITHOUT ROWID;
CREATE INDEX forum_comment_votes_user_idx ON forum_comment_votes (user_id);

------------------------------------------------------------------------------
-- Reports

CREATE TABLE reports (
  id TEXT PRIMARY KEY NOT NULL,
  reporter_id TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  target_type TEXT NOT NULL CHECK (target_type IN ('user', 'message', 'forum_post', 'forum_comment')),
  target_id TEXT NOT NULL,
  target_user_id TEXT REFERENCES profiles (id) ON DELETE SET NULL,
  target_username TEXT,
  content_snapshot TEXT,
  reason TEXT NOT NULL CHECK (reason IN ('spam', 'harassment', 'inappropriate', 'scam', 'impersonation', 'other')),
  details TEXT CHECK (details IS NULL OR length(details) <= 1000),
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'actioned', 'dismissed')),
  admin_note TEXT CHECK (admin_note IS NULL OR length(admin_note) <= 1000),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  resolved_at TEXT,
  resolved_by TEXT REFERENCES profiles (id) ON DELETE SET NULL
);
CREATE INDEX reports_status_created_idx ON reports (status, created_at DESC);
CREATE INDEX reports_reporter_created_idx ON reports (reporter_id, created_at DESC);
CREATE UNIQUE INDEX reports_one_open_per_target ON reports (reporter_id, target_type, target_id) WHERE status = 'open';

------------------------------------------------------------------------------
-- Pokémon Bank wind-down (retires after 26 February 2027)

CREATE TABLE bank_checklist (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK (length(trim(label)) BETWEEN 1 AND 60),
  form_id INTEGER,
  shiny INTEGER NOT NULL DEFAULT 0 CHECK (shiny IN (0, 1)),
  location TEXT NOT NULL DEFAULT 'bank' CHECK (location IN ('bank', 'game_3ds', 'game_ds', 'game_gba')),
  box_note TEXT CHECK (box_note IS NULL OR length(box_note) <= 80),
  hold_for_ribbons INTEGER NOT NULL DEFAULT 0 CHECK (hold_for_ribbons IN (0, 1)),
  moved_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX bank_checklist_user_idx ON bank_checklist (user_id, created_at);
CREATE INDEX bank_checklist_form_idx ON bank_checklist (form_id);

CREATE TRIGGER bank_checklist_limit BEFORE INSERT ON bank_checklist
WHEN (SELECT count(*) FROM bank_checklist WHERE user_id = NEW.user_id) >= 3000
BEGIN
  SELECT RAISE(ABORT, 'The checklist holds up to 3,000 Pokémon, same as Bank.');
END;

CREATE TABLE ribbon_plans (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  label TEXT NOT NULL CHECK (length(trim(label)) BETWEEN 1 AND 60),
  form_id INTEGER,
  shiny INTEGER NOT NULL DEFAULT 0 CHECK (shiny IN (0, 1)),
  origin TEXT NOT NULL
    CHECK (origin IN ('rse', 'frlg', 'colosseum-xd', 'dppt', 'hgss', 'bw', 'b2w2', 'xy', 'oras', 'sm', 'usum', 'vc')),
  current_stage TEXT NOT NULL CHECK (current_stage IN ('gen3', 'gen4', 'gen5', 'gen6', 'gen7', 'home')),
  completed_ribbons TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(completed_ribbons) AND json_type(completed_ribbons) = 'array'),
  skipped_ribbons TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(skipped_ribbons) AND json_type(skipped_ribbons) = 'array'),
  notes TEXT CHECK (notes IS NULL OR length(notes) <= 500),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX ribbon_plans_form_idx ON ribbon_plans (form_id);
CREATE INDEX ribbon_plans_user_idx ON ribbon_plans (user_id, created_at);

CREATE TRIGGER ribbon_plans_limit BEFORE INSERT ON ribbon_plans
WHEN (SELECT count(*) FROM ribbon_plans WHERE user_id = NEW.user_id) >= 100
BEGIN
  SELECT RAISE(ABORT, 'You can have up to 100 Ribbon Master plans.');
END;

-- Admin-curated, so it stays in the database rather than the static files:
-- the Admin page edits it live.
CREATE TABLE bank_last_chance (
  id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE CHECK (length(slug) >= 1 AND slug NOT GLOB '*[^a-z0-9-]*' AND slug NOT GLOB '-*' AND slug NOT GLOB '*-' AND slug NOT GLOB '*--*'),
  title TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 120),
  category TEXT NOT NULL CHECK (category IN ('origin', 'ribbon', 'event', 'form', 'other')),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 1000),
  species_id INTEGER,
  form_id INTEGER,
  source_url TEXT CHECK (source_url IS NULL OR substr(source_url, 1, 8) = 'https://'),
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_published INTEGER NOT NULL DEFAULT 1 CHECK (is_published IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX bank_last_chance_form_idx ON bank_last_chance (form_id) WHERE form_id IS NOT NULL;
CREATE INDEX bank_last_chance_species_idx ON bank_last_chance (species_id) WHERE species_id IS NOT NULL;

CREATE TABLE bank_last_chance_done (
  user_id TEXT NOT NULL REFERENCES profiles (id) ON DELETE CASCADE,
  entry_id INTEGER NOT NULL REFERENCES bank_last_chance (id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (user_id, entry_id)
) WITHOUT ROWID;
CREATE INDEX bank_last_chance_done_entry_idx ON bank_last_chance_done (entry_id);

------------------------------------------------------------------------------
-- updated_at, kept fresh the way the Supabase set_updated_at triggers did.
-- Recursive triggers are off in SQLite, so the inner UPDATE doesn't refire.

CREATE TRIGGER profiles_set_updated_at AFTER UPDATE ON profiles
BEGIN UPDATE profiles SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id; END;
CREATE TRIGGER collection_progress_set_updated_at AFTER UPDATE ON collection_progress
BEGIN UPDATE collection_progress SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE user_id = NEW.user_id AND form_id = NEW.form_id; END;
CREATE TRIGGER game_collection_progress_set_updated_at AFTER UPDATE ON game_collection_progress
BEGIN UPDATE game_collection_progress SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE user_id = NEW.user_id AND game_id = NEW.game_id AND species_id = NEW.species_id; END;
CREATE TRIGGER game_form_collection_progress_set_updated_at AFTER UPDATE ON game_form_collection_progress
BEGIN UPDATE game_form_collection_progress SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE user_id = NEW.user_id AND game_id = NEW.game_id AND form_id = NEW.form_id; END;
CREATE TRIGGER user_collection_views_set_updated_at AFTER UPDATE ON user_collection_views
BEGIN UPDATE user_collection_views SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id; END;
CREATE TRIGGER user_form_preferences_set_updated_at AFTER UPDATE ON user_form_preferences
BEGIN UPDATE user_form_preferences SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE user_id = NEW.user_id; END;
CREATE TRIGGER bank_checklist_set_updated_at AFTER UPDATE ON bank_checklist
BEGIN UPDATE bank_checklist SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id; END;
CREATE TRIGGER ribbon_plans_set_updated_at AFTER UPDATE ON ribbon_plans
BEGIN UPDATE ribbon_plans SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id; END;
CREATE TRIGGER bank_last_chance_set_updated_at AFTER UPDATE ON bank_last_chance
BEGIN UPDATE bank_last_chance SET updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE id = NEW.id; END;
